// TestImageE2E_GoldenReady is the image-enrichment (Phase B2) AC-1 golden — the
// counterpart to integration_async_test.go (the B1 TV golden). It drives the FULL
// image pipeline with REAL go-plugin subprocesses (base-scanner + tv-parser +
// image-enricher) + the REAL system exiftool over REAL image fixtures, and asserts
// the ASYNC image model: scan returns non-blocking, the B1 worker pool drains the
// image-enricher chain in the background, and each image item settles enriched ->
// ready with sources["image-enricher"] carrying real EXIF + core-stamped
// _provenance/_view/_stages. No in-process fakes on the hot path (AC-1 Verify
// probe): all four binaries are freshly built into a temp dir; fixtures are real
// image files generated at test time (stdlib jpeg/png + exiftool-stamped EXIF +
// ffmpeg webp + sips heic). Skips cleanly under -short / missing exiftool. The
// AC-2/AC-3 structural probes (no-CGO, go.mod untouched, additive diff) are run as
// the delegation's bash gate (they are git/grep probes by nature).
package mellifera_test

import (
	"image"
	"image/jpeg"
	"image/png"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"
)

const (
	imgToken         = "image-admin-token"
	imgDrainTimeout  = 20 * time.Second // bounds the worker-pool drain poll (exiftool-per-item is slower than TV)
	imgExifMake      = "Apple"
	imgExifModel     = "iPhone 15"
	imgExifDT        = "2024:07:30 14:21:05"  // exiftool -n machine form (stamped)
	imgExifDTRFC3339 = "2024-07-30T14:21:05Z" // enricher normalizeExifDate output
	imgExifOrient    = 6
	imgExifGPSLat    = 55.7558
	imgExifGPSLon    = 37.6173
	imgCyrillicModel = "Фотоаппарат" // AC-unicode: non-ASCII Model preserved verbatim
)

// TestImageE2E_GoldenReady builds the real server + base-scanner + tv-parser +
// image-enricher, starts the server (temp SQLite + free port + ALL plugin envs incl
// MELLIFERA_IMAGE_ENRICHER — hermetic), scans a real image fixture library
// (module_id=image), and asserts the async image model + real EXIF provenance over
// a bounded poll-to-settle.
func TestImageE2E_GoldenReady(t *testing.T) {
	if testing.Short() {
		t.Skip("image integration test: skips under -short (builds binaries + subprocess)")
	}
	if _, err := exec.LookPath("exiftool"); err != nil {
		t.Skip("exiftool not on PATH — skipping image AC-1 golden (INV-skip-clean); structural probes run via the gate")
	}

	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "img-server", "./cmd/mellifera")
	scannerBin := buildBinary(t, tmp, "img-base-scanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "img-tv-parser", "./plugins/tv-parser")
	imageEnricherBin := buildBinary(t, tmp, "img-image-enricher", "./plugins/image-enricher")
	fixtures := imgWriteFixtureRoot(t)

	baseURL := startServer(t, serverBin, scannerBin, tvParserBin, imageEnricherBin, tmp, imgToken)
	client := &http.Client{Timeout: httpTimeout}
	libID := imgCreateLibrary(t, client, baseURL, imgToken, fixtures.root)

	res := scanLibrary(t, client, baseURL, imgToken, libID)
	t.Run("AC1_async_nonblocking_and_module_gating", func(t *testing.T) {
		imgAssertNonBlockingAndGating(t, client, baseURL, libID, res, fixtures)
	})

	// AC-1: bounded poll until every discovered image item reaches the ready drain
	// terminal (image-enricher writes sources.image-enricher -> B1 settle).
	byRel := imgWaitForReady(t, client, baseURL, libID, fixtures.rels, imgDrainTimeout)

	t.Run("AC1_image_EXIF_provenance", func(t *testing.T) { imgAssertEXIFGolden(t, byRel) })
	t.Run("AC_softfail_noexif_and_corrupt", func(t *testing.T) { imgAssertSoftFail(t, byRel) })
	t.Run("AC_unicode_cyrillic", func(t *testing.T) { imgAssertUnicode(t, byRel) })
	t.Run("AC_image_heic", func(t *testing.T) { imgAssertHEIC(t, byRel, fixtures) })
}

// imgAssertNonBlockingAndGating asserts AC-queue (scan returned WITHOUT awaiting
// enrichment — at least one item is still in-flight right after the response) and
// AC-image module-type gating (the stray .mkv is NOT discovered; only image exts
// are). The scan-response shape (200 + Discovered/Persisted, returned before this
// read) is the structural non-blocking proof.
func imgAssertNonBlockingAndGating(t *testing.T, c *http.Client, baseURL string, libID int64, res scanResponse, fx imgFixtures) {
	t.Helper()
	if want := len(fx.rels); res.Discovered != want || res.Persisted != want {
		t.Fatalf("AC-1: scan discovered=%d persisted=%d, want %d (image fixtures only; .mkv gated out)", res.Discovered, res.Persisted, want)
	}
	if len(fx.rels) < 4 {
		t.Fatalf("AC-1: only %d image fixtures discovered, want >=4 (B01)", len(fx.rels))
	}
	items := listItems(t, c, baseURL, imgToken, libID)
	ready := 0
	for _, it := range items {
		if it.Status == "ready" {
			ready++
		}
	}
	// AC-queue: enrichment was not awaited inline — N exiftool subprocesses cannot
	// all complete between scan-return and this GET, so >=1 item is still in-flight.
	if ready == len(items) && len(items) > 0 {
		t.Errorf("AC-queue: all %d items already ready the instant scan returned — scan blocked on enrichment", len(items))
	}
	if _, leak := indexByPath(t, items)["not_video.mkv"]; leak {
		t.Errorf("AC-image: not_video.mkv was discovered by the image module (module-type gating failed)")
	}
}

// imgAssertEXIFGolden asserts AC-1/AC-image for the EXIF-rich JPEG: sources.
// image-enricher carries real EXIF (dimensions/format + make/model/date-taken/
// orientation/GPS), _provenance names image-enricher per field, a _view entry
// sources image-enricher, _stages records an ok image-enricher entry, and base
// ffprobe (stdlib discovery) is non-empty for the decodable jpeg.
func imgAssertEXIFGolden(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	const rel = "IMG_2024.jpg"
	it, ok := byRel[rel]
	if !ok {
		t.Fatalf("AC-1: %q not persisted; have %v", rel, pathsOf(byRel))
	}
	if it.Status != "ready" {
		t.Fatalf("AC-1: %q status = %q, want ready (the async image drain terminal)", rel, it.Status)
	}
	doc := parseAsyncDoc(t, it.Document)
	ns, ok := doc.Sources["image-enricher"]
	if !ok {
		t.Fatalf("AC-1: %q sources.image-enricher missing (sources=%v)", rel, doc.Sources)
	}
	if w, _ := imgNum(ns, "width"); w <= 0 {
		t.Errorf("AC-1: %q sources.image-enricher.width = %v, want >0", rel, ns["width"])
	}
	if h, _ := imgNum(ns, "height"); h <= 0 {
		t.Errorf("AC-1: %q sources.image-enricher.height = %v, want >0", rel, ns["height"])
	}
	if got := asyncStr(ns, "format"); got != "jpeg" {
		t.Errorf("AC-1: %q sources.image-enricher.format = %q, want jpeg", rel, got)
	}
	if got := asyncStr(ns, "make"); got != imgExifMake {
		t.Errorf("AC-1: %q sources.image-enricher.make = %q, want %q", rel, got, imgExifMake)
	}
	if got := asyncStr(ns, "model"); got != imgExifModel {
		t.Errorf("AC-1: %q sources.image-enricher.model = %q, want %q", rel, got, imgExifModel)
	}
	if got := asyncStr(ns, "date_taken"); got != imgExifDTRFC3339 {
		t.Errorf("AC-1: %q sources.image-enricher.date_taken = %q, want %q", rel, got, imgExifDTRFC3339)
	}
	if got, _ := imgNum(ns, "orientation"); int(got) != imgExifOrient {
		t.Errorf("AC-1: %q sources.image-enricher.orientation = %v, want %d", rel, ns["orientation"], imgExifOrient)
	}
	if lat, ok := imgNum(ns, "gps_lat"); !ok || imgAbs(lat-imgExifGPSLat) > 0.01 {
		t.Errorf("AC-1: %q sources.image-enricher.gps_lat = %v, want ~%v", rel, ns["gps_lat"], imgExifGPSLat)
	}
	if lon, ok := imgNum(ns, "gps_lon"); !ok || imgAbs(lon-imgExifGPSLon) > 0.01 {
		t.Errorf("AC-1: %q sources.image-enricher.gps_lon = %v, want ~%v", rel, ns["gps_lon"], imgExifGPSLon)
	}
	imgAssertProvenanceAndView(t, rel, doc, "width")
	if len(doc.Ffprobe) == 0 {
		t.Errorf("AC-image: %q base ffprobe empty, want non-empty {width,height,format} from stdlib discovery", rel)
	}
}

// imgAssertSoftFail asserts AC-softfail: (a) a NO-EXIF image (photo.png) is a CLEAN
// success — exiftool still returns {width,height,format} (not a spurious no_data) —
// and settles ready; (b) a corrupt/truncated image is still PERSISTED (one bad file
// never aborts the library) with an empty base ffprobe.
func imgAssertSoftFail(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	pngItem, ok := byRel["photo.png"]
	if !ok {
		t.Fatalf("AC-softfail: photo.png not persisted; have %v", pathsOf(byRel))
	}
	if pngItem.Status != "ready" {
		t.Errorf("AC-softfail: photo.png status = %q, want ready (no-EXIF is a clean success, not no_data)", pngItem.Status)
	}
	pngNS := parseAsyncDoc(t, pngItem.Document).Sources["image-enricher"]
	if w, _ := imgNum(pngNS, "width"); w <= 0 {
		t.Errorf("AC-softfail: photo.png sources.image-enricher.width = %v, want >0 (no-EXIF still yields dims)", pngNS["width"])
	}
	if got := asyncStr(pngNS, "format"); got != "png" {
		t.Errorf("AC-softfail: photo.png sources.image-enricher.format = %q, want png", got)
	}
	for _, absent := range []string{"make", "model", "date_taken", "orientation", "gps_lat", "gps_lon"} {
		if _, leak := pngNS[absent]; leak {
			t.Errorf("AC-softfail: photo.png sources.image-enricher.%s present, want absent (no EXIF)", absent)
		}
	}
	trunc, ok := byRel["truncated.jpg"]
	if !ok {
		t.Fatalf("AC-softfail: truncated.jpg not persisted (a corrupt image must still yield an item); have %v", pathsOf(byRel))
	}
	if fp := parseAsyncDoc(t, trunc.Document).Ffprobe; len(fp) != 0 {
		t.Errorf("AC-softfail: truncated.jpg base ffprobe = %d bytes, want empty (undecodable soft-fail)", len(fp))
	}
}

