// imgAssertProvenanceAndView asserts the core-stamped provenance/view/stages
// contract for one enriched field: _provenance[field] names image-enricher with a
// non-empty version, >=1 _view entry sources image-enricher, and _stages records an
// ok image-enricher entry.
func imgAssertProvenanceAndView(t *testing.T, rel string, doc asyncDoc, field string) {
	t.Helper()
	if p, present := doc.Provenance[field]; present {
		if got := asyncStr(p, "plugin_id"); got != "image-enricher" {
			t.Errorf("AC-1: %q _provenance.%s.plugin_id = %q, want image-enricher", rel, field, got)
		}
		if asyncStr(p, "plugin_version") == "" {
			t.Errorf("AC-1: %q _provenance.%s.plugin_version empty", rel, field)
		}
	} else {
		t.Errorf("AC-1: %q _provenance.%s missing", rel, field)
	}
	sourced := false
	for _, v := range doc.View {
		if asyncStr(v, "source") == "image-enricher" {
			sourced = true
			break
		}
	}
	if !sourced {
		t.Errorf("AC-1: %q no _view entry sources image-enricher; view=%v", rel, doc.View)
	}
	if !asyncStageHas(doc.Stages, "image-enricher", "ok") {
		t.Errorf("AC-1: %q no _stages entry {image-enricher, status:ok}; stages=%v", rel, doc.Stages)
	}
}

// imgWaitForReady polls the item listing until every rel is 'ready', or fails with
// the last observed per-item statuses (INV-poll-bounded).
func imgWaitForReady(t *testing.T, c *http.Client, baseURL string, libID int64, rels []string, timeout time.Duration) map[string]itemDTO {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		byRel := indexByPath(t, listItems(t, c, baseURL, imgToken, libID))
		if imgAllReady(byRel, rels) {
			return byRel
		}
		time.Sleep(probeInterval)
	}
	byRel := indexByPath(t, listItems(t, c, baseURL, imgToken, libID))
	t.Fatalf("image drain did not settle %v to ready within %s; last: %s", rels, timeout, imgStatuses(byRel))
	return byRel
}

func imgAllReady(byRel map[string]itemDTO, rels []string) bool {
	for _, rel := range rels {
		it, ok := byRel[rel]
		if !ok || it.Status != "ready" {
			return false
		}
	}
	return true
}

func imgStatuses(byRel map[string]itemDTO) string {
	out := make([]string, 0, len(byRel))
	for rel, it := range byRel {
		out = append(out, rel+"="+it.Status)
	}
	return strings.Join(out, " ")
}

// imgNum reads a JSON numeric namespace field (structpb emits float64); ok=false
// when absent or non-numeric. Mirrors asyncInt but keeps the float (GPS/dims).
func imgNum(m map[string]any, k string) (float64, bool) {
	switch n := m[k].(type) {
	case float64:
		return n, true
	case int:
		return float64(n), true
	}
	return 0, false
}

func imgAbs(f float64) float64 {
	if f < 0 {
		return -f
	}
	return f
}

// imgFixtures describes the generated image library: root + the discovered image
// relative paths (+ heicRel when a HEIC fixture was produced; "" otherwise).
type imgFixtures struct {
	root    string
	rels    []string
	heicRel string
}

// imgWriteFixtureRoot builds the real image fixture tree: an EXIF-rich JPEG, an
// EXIF-less PNG, a WEBP, a HEIC (when sips is available), a Cyrillic-named JPEG
// (non-ASCII Model), a truncated JPEG (corrupt), and a stray .mkv (must NOT be
// discovered). JPEG/PNG are stdlib-encoded; EXIF is stamped by the real exiftool;
// WEBP by ffmpeg; HEIC by sips. All image files are real on-disk files.
func imgWriteFixtureRoot(t *testing.T) imgFixtures {
	t.Helper()
	root := t.TempDir()
	fx := imgFixtures{root: root}

	exifJPG := filepath.Join(root, "IMG_2024.jpg")
	imgEncode(t, exifJPG, 64, 48, "jpeg")
	imgStampEXIF(t, exifJPG, imgExifMake, imgExifModel, imgExifDT, imgExifOrient, imgExifGPSLat, imgExifGPSLon)
	fx.rels = append(fx.rels, "IMG_2024.jpg")

	imgEncode(t, filepath.Join(root, "photo.png"), 32, 32, "png")
	fx.rels = append(fx.rels, "photo.png")

	if webpRel, ok := imgGenWebP(t, root, "shot.webp", 24, 24); ok {
		fx.rels = append(fx.rels, webpRel)
	}
	if heicRel, ok := imgGenHEIC(t, root, "HEIC_shot.heic", 32, 32); ok {
		fx.rels = append(fx.rels, heicRel)
		fx.heicRel = heicRel
	}

	// Cyrillic JPEG — reuses the full EXIF stamp with a non-ASCII Model so the
	// unicode case mirrors a real photo (other fields present is harmless; the
	// unicode assertion checks model verbatim).
	cyrJPG := filepath.Join(root, "Фото.jpg")
	imgEncode(t, cyrJPG, 48, 48, "jpeg")
	imgStampEXIF(t, cyrJPG, imgExifMake, imgCyrillicModel, imgExifDT, imgExifOrient, imgExifGPSLat, imgExifGPSLon)
	fx.rels = append(fx.rels, "Фото.jpg")

	mustWrite(t, filepath.Join(root, "truncated.jpg"), []byte("\xff\xd8\xff\xe0NOTAREALJPEG"))
	fx.rels = append(fx.rels, "truncated.jpg")

	// Stray .mkv — must NOT be discovered by the image module (AC-image gating).
	mustWrite(t, filepath.Join(root, "not_video.mkv"), []byte("not a video"))
	return fx
}

// imgEncode encodes a solid WxH image at path via the stdlib jpeg or png encoder.
func imgEncode(t *testing.T, path string, w, h int, format string) {
	t.Helper()
	f, err := os.Create(path)
	if err != nil {
		t.Fatalf("create %s: %v", filepath.Base(path), err)
	}
	defer f.Close()
	img := imgSolid(w, h)
	var encErr error
	if format == "png" {
		encErr = png.Encode(f, img)
	} else {
		encErr = jpeg.Encode(f, img, &jpeg.Options{Quality: 50})
	}
	if encErr != nil {
		t.Fatalf("%s encode %s: %v", format, filepath.Base(path), encErr)
	}
}

// imgSolid returns a solid opaque WxH RGBA image; pixel color is irrelevant
// (exiftool/the stdlib read the header/dims, which is what the golden asserts).
func imgSolid(w, h int) *image.RGBA {
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for i := 0; i < len(img.Pix); i += 4 {
		img.Pix[i] = 200   // R
		img.Pix[i+3] = 255 // A (opaque so jpeg — no alpha — encodes a defined image)
	}
	return img
}

// imgStampEXIF stamps real exiftool EXIF tags onto a JPEG (arg-slice ONLY, NEVER a
// shell — mirrors the enricher's own exiftool invocation). -n forces numeric values
// (Orientation sticks; GPS as decimals; date in EXIF machine form). Recon-verified
// against exiftool 13.55.
func imgStampEXIF(t *testing.T, path, make, model, dt string, orient int, lat, lon float64) {
	t.Helper()
	args := []string{
		"-overwrite_original", "-q", "-n",
		"-Make=" + make,
		"-Model=" + model,
		"-DateTimeOriginal=" + dt,
		"-Orientation=" + strconv.Itoa(orient),
		"-GPSLatitude=" + strconv.FormatFloat(lat, 'f', -1, 64),
		"-GPSLongitude=" + strconv.FormatFloat(lon, 'f', -1, 64),
		path,
	}
	if out, err := exec.Command("exiftool", args...).CombinedOutput(); err != nil {
		t.Fatalf("exiftool stamp %s: %v: %s", filepath.Base(path), err, out)
	}
}

// imgGenWebP generates a WxH WEBP via ffmpeg's libwebp encoder. Returns ("", false)
// when ffmpeg is unavailable — the WEBP sub-case is then simply absent (the
// jpg/png/heic/cyrillic golden still stands).
func imgGenWebP(t *testing.T, root, name string, w, h int) (string, bool) {
	t.Helper()
	return imgGenViaFFmpeg(t, root, name, w, h, "libwebp")
}

// imgGenHEIC generates a WxH HEIC via macOS sips (convert from a stdlib JPEG).
// Returns ("", false) when sips is unavailable — the HEIC edge is then skipped
// (acceptance.md AC-image HEIC coverage also lives in QA1's golden).
func imgGenHEIC(t *testing.T, root, name string, w, h int) (string, bool) {
	t.Helper()
	if _, err := exec.LookPath("sips"); err != nil {
		t.Logf("sips not on PATH — skipping HEIC fixture %q", name)
		return "", false
	}
	src := filepath.Join(root, ".heic-src.jpg")
	imgEncode(t, src, w, h, "jpeg")
	path := filepath.Join(root, name)
	out, err := exec.Command("sips", "-s", "format", "heic", src, "--out", path).CombinedOutput()
	_ = os.Remove(src)
	if err != nil {
		t.Logf("sips heic %s unavailable: %v: %s — skipping HEIC fixture", name, err, out)
		return "", false
	}
	if info, e := os.Stat(path); e != nil || info.Size() == 0 {
		return "", false
	}
	return name, true
}

// imgGenViaFFmpeg generates a WxH image at root/name via ffmpeg's lavfi testsrc and
// the given codec. Returns ("", false) when ffmpeg is unavailable or the encode
// fails — the sub-case is then simply absent from the fixture set.
func imgGenViaFFmpeg(t *testing.T, root, name string, w, h int, codec string) (string, bool) {
	t.Helper()
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Logf("ffmpeg not on PATH — skipping fixture %q", name)
		return "", false
	}
	path := filepath.Join(root, name)
	cmd := exec.Command("ffmpeg", "-hide_banner", "-loglevel", "error",
		"-f", "lavfi", "-i", "testsrc=duration=0.1:size="+strconv.Itoa(w)+"x"+strconv.Itoa(h)+":rate=5",
		"-frames:v", "1", "-c:v", codec, "-y", path)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Logf("ffmpeg %s %s unavailable: %v: %s — skipping fixture", codec, name, err, out)
		return "", false
	}
	if info, e := os.Stat(path); e != nil || info.Size() == 0 {
		return "", false
	}
	return name, true
}

// imgCreateLibrary POSTs an IMAGE library (module_id=image) and returns its id.
// createLibrary in integration_test.go hardcodes module_id "tv"; this is the
// image-module peer — the API already accepts an arbitrary module_id (AC-3).
func imgCreateLibrary(t *testing.T, c *http.Client, baseURL, token, root string) int64 {
	t.Helper()
	body := struct {
		ModuleID    string `json:"module_id"`
		RootPath    string `json:"root_path"`
		DisplayName string `json:"display_name"`
	}{ModuleID: "image", RootPath: root, DisplayName: "Integration Image"}
	var resp libraryResponse
	status := doRequest(t, c, http.MethodPost, baseURL+"/api/v1/libraries", token, body, &resp)
	if status != http.StatusCreated {
		t.Fatalf("create image library: HTTP %d, want 201", status)
	}
	return resp.ID
}
